// Generated from Content/Ships: the server files of the two default respawn ships, so a dedicated server whose
// update left Content/Ships out (a 0.17 runner applies the first 0.18 update) still has them. Pictures stay in Content.
namespace Y51_SE2Online.Sync;

internal static class DefaultShipFiles
{
    /// <summary>Writes a default ship's server files into <paramref name="shipsFolder"/>\&lt;folder&gt;; false when <paramref name="folder"/>
    /// is not one of them. Existing files are left alone.</summary>
    public static bool Unpack(string shipsFolder, string folder)
    {
        bool any = false;
        foreach (var (name, file, data) in Files)
        {
            if (!string.Equals(name, folder, System.StringComparison.OrdinalIgnoreCase)) continue;
            any = true;
            string dir = System.IO.Path.Combine(shipsFolder, name), path = System.IO.Path.Combine(dir, file);
            if (System.IO.File.Exists(path)) continue;
            System.IO.Directory.CreateDirectory(dir);
            System.IO.File.WriteAllBytes(path, System.Convert.FromBase64String(data));
        }
        return any;
    }

    public static readonly (string Folder, string File, string Base64)[] Files =
    {
        ("SE1 Banana Boat", ".container-info", ""),
        ("SE1 Banana Boat", "grid.json.vrb", ""),
        ("SE1 Banana Boat", "snapshot.vrb", ""),
        ("SE1 Atmospheric Lander", ".container-info", ""),
        ("SE1 Atmospheric Lander", "grid.json.vrb", ""),
        ("SE1 Atmospheric Lander", "snapshot.vrb", ""),
    };
}
